 void onlyTask(String pool,String task)throws Exception{var rows=j.queryForList("SELECT id,state FROM durable_task WHERE pool=? AND state IN ('READY','RUNNING','RECONCILING') ORDER BY id",pool);assertEquals(List.of(task),rows.stream().map(x->(String)x.get("id")).toList(),"Never claim unrelated pool work");Files.writeString(receipt.resolve("b1-pool-before-"+pool+".json"),json.writeValueAsString(Map.of("pool",pool,"selectedTask",task,"actual",rows)));}
 void await(String task)throws Exception{long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(40);String state;do{state=j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,task);if(Set.of("SUCCEEDED","FAILED","CANCELLED","STALE").contains(state))break;Thread.sleep(50);}while(System.nanoTime()<end);assertEquals("SUCCEEDED",state,"Preserve exact failed task; never recreate");}
 HttpResponse<String> as(String session,String method,String path)throws Exception{String previous=token;token=session;try{var response=call(method,path,"",null);http.add(Map.of("method",method,"path",path,"status",response.statusCode(),"body",response.body()));return response;}finally{token=previous;}}
 void phase(String next)throws Exception{phase=next;var value=new LinkedHashMap<String,Object>();value.put("phase",phase);value.put("meeting",meeting);value.put("owner",owner);value.put("generationTask",generationTask);value.put("modelStore",modelStore==null?null:modelStore.toString());Files.writeString(receipt.resolve("b1-continuation.json"),json.writeValueAsString(value));}
 Map<String,String> protectedFacts()throws Exception{return protectedFacts(j);}
 Map<String,String> protectedFacts(org.springframework.jdbc.core.JdbcTemplate selectedJdbc)throws Exception{var result=new TreeMap<String,String>();String ids="'1f910de1-f37a-4013-9fdf-8cf4b97ebc72','b480f02c-b336-41a1-bda6-ab2db4cc279c','bdd60786-afd3-49fd-91b8-c4ed13e6bc3c'";for(String table:List.of("meeting","publication","final_confirmation")){String field=table.equals("meeting")?"id":"meeting_id";result.put(table,hash(selectedJdbc.queryForList("SELECT * FROM "+table+" WHERE "+field+" IN ("+ids+") ORDER BY id").toString()));}result.put("tasks",hash(selectedJdbc.queryForList("SELECT * FROM durable_task WHERE subject_kind='MEETING' AND subject_id IN ("+ids+") ORDER BY id").toString()));result.put("operations",hash(selectedJdbc.queryForList("SELECT * FROM external_operation WHERE subject_kind='MEETING' AND subject_id IN ("+ids+") ORDER BY id").toString()));result.put("executions",hash(selectedJdbc.queryForList("SELECT e.* FROM external_execution e JOIN external_operation o ON o.id=e.operation_id WHERE o.subject_kind='MEETING' AND o.subject_id IN ("+ids+") ORDER BY e.operation_id,e.execution_no").toString()));return result;}
